import pytest
from candidate import car_race_collision

class TestCarRaceCollision:
    def test_car_race_collision_normalcase(self, n):
        assert car_race_collision(5) == 25

    def test_car_race_collision_boundary_case_zero(self):
        assert car_race_collision(0) == 0

    def test_car_race_collision_negative_input(self):
        with pytest.raises(ValueError):
            car_race_collision(-5)

    def test_car_race_collision_none_input(self):
        with pytest.raises(TypeError):
            car_race_collision(None)

    def test_car_race_collision_edge_case_single_car(self):
        assert car_race_collision(1) == 1

    def test_car_race_collision_edge_case_double_cars(self):
        assert car_race_collision(2) == 4
